function OverseaManagePersonnelRoleDialog:InitFeedEnv()
    for i, v in pairs(FeedIds) do
        local goodItem = self["GoodsGroup"..i]
        if goodItem then
            local env = CfUtils.GetLuaScr(goodItem,FeedNodePath)
            if isNotNull(env) then
                env:SetCallBack(Bind(self,self.OnGoodNodeClick))
                env:RefreshShow(v)
                table.insert(self.feedEnv,env)
            end
        end
    end
end

function OverseaManagePersonnelRoleDialog:RefreshFeedShow()
    for i, v in pairs(self.feedEnv) do
        v:RefreshNodeShow()
    end
end

function OverseaManagePersonnelRoleDialog:OnGoodNodeClick(goodsId)
    if isNotNull(self.curVo) then
        local level = tonumber(self.curVo.favorabilityLevel)
        local curMood = MaidCoffeeUtils.GetCurMoodByCardFavorabilityLevel(self.curVo.cardId,level)
        if self.curVo.cafeEnergy >= curMood then
            GameUtils.Toast(localize("当前员工心情值已满"))
            return
        end
        GameUtils.Request(Interfaces.MaidCoffeeFeed,{snackId = goodsId,playerCardId = self.curVo.id},function(request,response)
            if checkNumber(response.errCode) == 0 then
                self.curVo.cafeEnergy = response.data.cafeEnergy
                local cardDojo = cardComponent:GetCardById(tonumber(self.curVo.id))
                cardDojo:UpdateCardEnergy(response.data.cafeEnergy,true)
                GoodsUtils.DrawRewards({ [1] = { goodsId = goodsId, num = -1} }, true)
                self:RefreshLeftInfo(self.curVo, true)
                self:RefreshFeedShow()
                if checkNumber(self.curSelectIndex) > 0 then
                    local go = self.ScrollView:GetShownItemByItemIndex(self.curSelectIndex - 1)
                    if go then
                        local env = CfUtils.GetLuaScr(go, UIPersonRoleCellPath)
                        if env then
                            env:SetSoulPoint()
                        end
                    end
                end
                Events.Broadcast("MaidCoffee_RecoverSoulPoint", self.curVo.id)
            end
        end)
    end
end

function OverseaManagePersonnelRoleDialog:GetCardDataByType()
    local limitType = self:GetLimitType()
    local limitStatus2Status = MaidCoffeeUtils.GetMaidCoffeeCardStatusLimit(limitType)
    -- print("limitStatus2Status", table.toString(limitStatus2Status))
    local isLounge = self.parameters.type ==MaidCoffeeConstants.SelectType.Lounge
    local allCards = cardComponent:GetAllCardTable()
    local showCard = {}
    for k, v in pairs(allCards) do
        local cardVo = MaidCoffeeUtils.GetCardManagerInfoVo(v.cardId)
        if cardVo then
            if isLounge then
                ---心情值不满 或者 卡牌状态是 在休息室中
                if MaidCoffeeUtils.CheckIsCanLoungeSelectCard(v, limitType, limitStatus2Status) then
                    table.insert(showCard,v)
                end
            else
                local jobs = cardVo.job
                for i, j in pairs(jobs) do
                    local job = tonumber(j)
                    if job == self.parameters.type then
                        local cafeStatus = checkNumber(v.cafeStatus)
                        if not limitStatus2Status[cafeStatus] then
                            if self.parameters.type == MaidCoffeeConstants.SelectType.DeliveryMan then
                                local isInIgnore = self:isInIgnore(v.cardId)
                                if not isInIgnore then
                                    table.insert(showCard,v)
                                end
                            else
                                table.insert(showCard,v)
                            end
                        end
                    end
                end

            end
        else
            printError("cardID =====%s 在 卡牌经营技能配置表 中没有找到",v.cardId)
        end
    end
    return showCard
end

function OverseaManagePersonnelRoleDialog:isInIgnore(cardId)
    if self.parameters.ignoreData and table.count(self.parameters.ignoreData) > 0 then
        if self.parameters.ignoreData[tostring(cardId)] then
            return true
        end
    end
    return false
end

function OverseaManagePersonnelRoleDialog:FillFilter()
    ---@type UICommonFilterMB
    local filterNodeEnv = CfUtils.GetLuaScr(self.CommonFilterNode.gameObject, 'Game.Behaviours.UICommonFilterMB')
    if not isNull(filterNodeEnv) then
        local sortType = Constants.UISortType.MaidCoffee
        local showCard = self:GetCardDataByType()
        filterNodeEnv:SetCallback(showCard, function(data)
            self.showData = self:GetAllCard(data)
            self:RefreshGridView(self.showData)
        end, sortType)
        filterNodeEnv:RestoreState("OverseaManagePersonnelRoleDialog", function(data)
            self.showData = self:GetAllCard(data)
            --self:RefreshGridView(self.showData)
        end)
    end
end
