function OverseaManagePersonnelRoleDialog:GetAllCard(data)
    local cardAll = data
    local t1 = {}
    local t2 = {}
    local tempData = {}
    for i, v in pairs(cardAll) do
        local isIn,pos = self:IsInStaff(v.id)
        if isIn then
            table.insert(tempData,{index = pos,vo = v})
        else
            table.insert(t2,v)
        end
    end
    ---保证有序
    table.sort(tempData,function(a,b) return a.index < b.index  end)
    for i, v in pairs(tempData) do
        table.insert(t1,v.vo)
    end

    table.insertto(t1,t2)
    return t1
end

function OverseaManagePersonnelRoleDialog:IsInStaff(id)
    for i, v in pairs(self.cacheData) do
        if tonumber(v.id) == tonumber(id) then
            return true, v.index
        end
    end
    return false,nil
end

