function OverseaManagePersonnelRoleDialog:OnGetItemByIndex(go, index, row, column)
    if index < 0 then
        return
    end
    local cellCardData = self.showData[index + 1]
    ---@type OverseaManagePersonnelRoleCell
    local scr = CfUtils.GetLuaScr(go, UIPersonRoleCellPath)
    if scr then
        local isIn, pos = self:IsInStaff(cellCardData.id)
        scr:RefreshChooseStatus(isIn,pos)
        scr:RefreshRoleData(cellCardData,function(isDel) self:OnCardClick(index + 1, isDel) end)
        if self.curSelectIndex and self.curSelectIndex == index + 1 then
            scr:SetSelectStatus(true)
        else
            scr:SetSelectStatus(false)
        end
    end
end

function OverseaManagePersonnelRoleDialog:OnCardClick(index)
    local cellCardData = self.showData[index]
    local lastSelectInd = checkNumber(self.curSelectIndex)
    self.curSelectIndex = checkInt(index)
    if checkNumber(lastSelectInd) > 0 then
        local go = self.ScrollView:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIPersonRoleCellPath)
            if lastScr then
                lastScr:SetSelectStatus(false)
            end
        end
    end

    if checkNumber(self.curSelectIndex) > 0 then
        local go = self.ScrollView:GetShownItemByItemIndex(self.curSelectIndex - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIPersonRoleCellPath)
            if lastScr then
                lastScr:SetSelectStatus(true)
                self:RefreshLeftInfo(cellCardData)
            end
        end
    end
end

