function OverseaManagePersonnelRoleDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            while not self.isRequest do
                coroutine.yield(Yielders.EndOfFrame)
            end
            self.ScrollView:InitListView(0, Bind(self, self.OnGetItemByIndex), nil, Bind(self, self.OnGetListItemByIndex))
            self.ScrollView:SetListItemCount(table.count(self.showData))
        end)
    end))
    return coWait
end

function OverseaManagePersonnelRoleDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            self.parameters = self.controller.Argument.parameters
            self.cacheData = maidCoffeeComponent:GetCacheData()
            self.isRequest = false
            self:RefreshStaticShow()
            GameUtils.Request(Interfaces.MaidCoffeeCardMood,{},function(request,response)
                if checkInt(response.errCode) == 0 then
                    local responseData = response.data
                    local cardsEnergy = responseData.cardsEnergy
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    for i, v in pairs(cardsEnergy) do
                        local cardDojo = cardComponent:GetCardById(tonumber(i))
                        if not isNull(cardDojo) then
                            cardDojo:UpdateCardEnergy(v,true)
                        else
                            printError("客户端 没有唯一id 为 %s 的卡牌，请联系服务器查询！！！！",checkString(i))
                        end
                    end
                    Events.Broadcast("MaidCoff.ChangeCardEnergy")
                    self:FillFilter()
                    self:RefreshCountShow()
                    self.isRequest = true
                end
            end)
        end)
    end))
    return coWait
end

function OverseaManagePersonnelRoleDialog:RefreshLeftInfo(vo, ignore)
    self.curVo = vo
    self.curCardId = vo.cardId
    local cardVo = CardConfMgr:GetInstance():GetCardByRefId(tonumber(vo.cardId))
    CfUtils.FillText(self.TextName,cardVo.descr)
    CfUtils.FillText(self.TextName2,cardVo.name)
    ---设置心情值和状态 会刷新
    local point = tonumber(vo.cafeEnergy) or 0

    MaidCoffeeUtils.FillSoulImage(self.ImgAttribute,point)
   
    local level = tonumber(vo.favorabilityLevel)
    local curMood = MaidCoffeeUtils.GetCurMoodByCardFavorabilityLevel(vo.cardId,level)

    local status = MaidCoffeeUtils.GetCardMoodStatus(point)
    local color = NumColor[status]

    self.Slider.value = point/curMood
    self.SoulPointTxt.text = string.format(color,point).."/"..curMood
    ---进度条也要变色
    local index = MaidCoffeeUtils.GetCardMoodStatus(point)
    self.Fill.Status = index

    KTool.SetActive(self.ImgLose.gameObject,point == 0)
    KTool.SetActive(self.TipsNode.gameObject,false)
    local canvasGroup = self.ManageSkillNode.transform:GetComponent(typeof(CanvasGroup))
    local alpha = point == 0 and 0.5 or 1
    canvasGroup.alpha = alpha


    local cardVo = MaidCoffeeUtils.GetCardManagerInfoVo(tonumber(vo.cardId))
    local skillVo = MaidCoffeeUtils.GetMaidCoffeeSkillInfoVo(cardVo.additionId)
    KTool.SetActive(self.ManageSkillNode.gameObject, not isNull(skillVo))
    if skillVo then
        self.SkillDesc.text = MaidCoffeeUtils.FillCoffeeSkillDescription(skillVo.decr,cardVo.additionNum,nil,cardVo.percentage)
        CfUtils.FillText(self.SkillName,skillVo.name)
        CfUtils.FillImage(self.SkillIcon,skillVo.icon)
    end
    self:SetLeftRootShow(true)
    self:RefreshBtnState(vo)
    
    if not ignore then
        CfUtils.SetActive(self.ContentFastRecoveryNode.gameObject,index == 1)
    end
end

