function OverseaManagePersonnelRoleDialog:SetTipNode(cardId)
    local vos = MaidCoffeeUtils.GetCardMoodsVos(cardId)
    if not isNull(vos) then
        if #vos > #self.tipsNodeGo then
            for i = #self.tipsNodeGo + 1, #vos  do
                local go = CS.UnityEngine.GameObject.Instantiate(self.TextDesc.gameObject)
                KTool.SetParent(go,self.TipsNode.gameObject,false)
                KTool.SetActive(go,false)
                table.insert(self.tipsNodeGo,go)
            end
        end

        for i, v in pairs(self.tipsNodeGo) do
            if not isNull(v) then
                if vos[i] then
                    KTool.SetActive(v,true)
                    local env = CfUtils.GetLuaScr(v,"Game.MaidCoffee.MaidCoffeeUIDialog.Cell.OverseaManagePersonnelRoleTipCell")
                    if env then
                        env:RefreshShow(vos[i])
                    end
                else
                    KTool.SetActive(v,false)
                end

            end
        end
    end
end

function OverseaManagePersonnelRoleDialog:RefreshBtnState(vo)
    local isIn = self:IsInStaff(vo.id)
    if isIn then
        self.BtnSure:GetComponent("FontStyleButton"):ResetFontStyle("B3", localize("取消"))
    else
        local status = checkNumber(vo.cafeStatus)
        local isCanClick = self:GetIsCanClickByType(status)
        if isCanClick then
            self.BtnSure:GetComponent("FontStyleButton"):ResetFontStyle("B5", localize("确定"))
        else
            self.BtnSure:GetComponent("FontStyleButton"):ResetFontStyle("B17", localize("无法选择"))
        end
    end
end
