function OverseaManagePersonnelRoleDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        xTry(function()
            for i, v in pairs(self.cacheData) do
                -----如果这里有在编队中的卡牌的时候  要从编队中拿掉
                ---@type MaidCoffeePlayerComponent
                local maidCoffeePlayerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.MaidCoffeePlayerComponent)
                maidCoffeePlayerComponent:RemoveTeamsPlayerId(v.id)
            end
            Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeRoleSelect,self.parameters.type,self.cacheData,self.parameters.index)
            self.controller = nil --删除lua层引⽤到的c#对象否则不会产⽣c# gc回收到对象
            self:Delete()
            self = nil --lua层的gc需要    
        end)
    end))
    return coWait
end

function OverseaManagePersonnelRoleDialog:__delete()
    self.controller = nil
    self.cacheData = nil
    for i, v in pairs(self.tipsNodeGo) do
        if not isNull(v) then
            CS.UnityEngine.GameObject.Destroy(v.gameObject)
        end
    end
end

function OverseaManagePersonnelRoleDialog:OnBtnSureClick()
    local vo = self.showData[self.curSelectIndex]
    local isIn = self:IsInStaff(vo.id)
    if isIn then
        local go = self.ScrollView:GetShownItemByItemIndex(self.curSelectIndex - 1)
        if go then
            for i, v in pairs(self.cacheData) do
                if v.id == tonumber(vo.id) then
                    v.id = 0
                    vo.cafeStatus = MaidCoffeeConstants.CafeStatus.Non
                    break
                end
            end
            self:SetCardStatusById(vo.id,MaidCoffeeConstants.CafeStatus.Non)
            local lastScr = CfUtils.GetLuaScr(go, UIPersonRoleCellPath)
            lastScr:RefreshChooseStatus(false)
            lastScr:RefreshWorkStatus()
            self:RefreshCountShow()
            self:RefreshLeftInfo(vo, true)
        end
    else
        local status = checkNumber(vo.cafeStatus)
        local isCanClick = self:GetIsCanClickByType(status)
        if isCanClick then
            if status ~= MaidCoffeeConstants.CafeStatus.Non then
                self:ShowSecondConfirm(status,vo)
            else
               self:OnSure(vo)
            end
        else
            local str = self:GetStrByStatus(status)
            GameUtils.Toast(str)
        end
    end
end

function OverseaManagePersonnelRoleDialog:OnBtnLevelUpClick()
    if isNull(self.curCardId) then
        return
    end
    ---@type CardProgressionUtils
    local CardProgressionUtils     = import("Game.CardProgression.CardProgressionUtils")
    local parameter = CardProgressionUtils.CheckJumpFavor(nil, { cardId = self.curCardId} )
    if parameter ~= nil then
        self.isGoTo = true
        CardProgressionUtils.OpenDialog(Constants.UITypeIds.CardProgressionIntroduction, parameter, UICommonUtils.GetShowDialogArguments())
    end
end

function OverseaManagePersonnelRoleDialog:OnBtnIllustrateClick()
    KTool.SetActive(self.TipsNode.gameObject,not self.TipsNode.gameObject.activeSelf)
    if self.TipsNode.gameObject.activeSelf then
        self:SetTipNode(self.curCardId)
    end
end

function OverseaManagePersonnelRoleDialog:OnBtnArrowClick()
    CfUtils.SetActive(self.ContentFastRecoveryNode.gameObject,not self.ContentFastRecoveryNode.gameObject.activeSelf)
end

function OverseaManagePersonnelRoleDialog:OnBtnLoseClick()
    if self.parameters.type == MaidCoffeeConstants.SelectType.Lounge then
        GameUtils.Toast(localize("您已在休息室中"))
        return
    end
    UIModule.OpenDialog(
            UIArgs(Constants.UITypeIds.OverManegeLoungeMainDialog, {}),
            {
                UIArgs(Constants.UITypeIds.UIMaidCoffeeManagerDialog),
                UIArgs(Constants.UITypeIds.UIMaidCoffeePersonMainDialog),
                UIArgs(Constants.UITypeIds.UIMaidCoffeeTakeoutPopupDialog),
                UIArgs(Constants.UITypeIds.UIMaidCoffeePersonSelectDialog),
            }
    )
end

function OverseaManagePersonnelRoleDialog:ShowSecondConfirm(status,vo)
    local isShow = tonumber(CfUtils.GetLocalData(self:GetLocalKey()))
    ---为1说明勾上了
    if isShow == 1 then
        self:OnSecondSure(status,vo)
    else
        local str = self:GetSecondConfirmStr(status)
        ---同一个角色踢人的操作
        GameUtils.SecondConfirm(str, function()
            self:OnSecondSure(status,vo)
        end, nil,nil,7,vo,nil,nil,function(isSelect)
            local result = isSelect and 1 or 0
            CfUtils.WriteLocalData(self:GetLocalKey(), result)
        end)
    end
end

function OverseaManagePersonnelRoleDialog:OnSecondSure(status,vo)
    local component = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.MaidCoffeeComponent)
    if status == MaidCoffeeConstants.CafeStatus.UnderManagement or
        status == MaidCoffeeConstants.CafeStatus.InService then
        local data = {}
        local count = CountNum[status]
        local posType = self:GetWorkTypeByStatus(status)
        for i = 1, count do
            local pos = posType * 100 + i
            local id = component:GetStaffInfoByType(posType ,i)
            if vo.id == id then
                data[tostring(pos)] = 0
            else
                data[tostring(pos)] = id
            end
        end
        GameUtils.Request(Interfaces.MaidCoffeeSetStaff, {staffs = table.serialize(data)}, function(request, response)
            if checkNumber(response.errCode) == 0 then
                vo.cafeStatus = MaidCoffeeConstants.CafeStatus.Non
                ---@type CardComponent
                local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                ---然后将新的卡放到当前位置上 然后更新状态
                for i, v in pairs(data) do
                    if tonumber(v) ~= 0 then
                        cardComponent:UpdateCardDojo(v, {cafeStatus = status})
                    end
                    component:UpdateStaffInfo(i,tonumber(v))
                end
                self:OnSure(vo)
                local isPersonHave = component:IsPersonHaveRedPoint()
                GameUtils.SetRedPointNum(Constants.RedPointConst.MaidCafeStaff,isPersonHave and 1 or 0)
            end
        end)
    elseif status == MaidCoffeeConstants.CafeStatus.InTakeaway then

    elseif status == MaidCoffeeConstants.CafeStatus.Resting then
        vo.cafeStatus = MaidCoffeeConstants.CafeStatus.Non
        self:OnSure(vo)
        Events.Broadcast(MaidCoffeeConstants.EventNames.MaidCoffeeRoleSelect,self.parameters.type,self.cacheData,self.parameters.index)
    end
end

function OverseaManagePersonnelRoleDialog:GetLocalKey()
    return table.concat({"PersonnelRoleDialog_PopSecondConfirm1_",tostring(self.cacheData.type)})
end

function OverseaManagePersonnelRoleDialog:GetSecondConfirmStr(status)
    local str = ""
    if status == MaidCoffeeConstants.CafeStatus.UnderManagement or status == MaidCoffeeConstants.CafeStatus.InService then
        str = localize("工作中")
    elseif status == MaidCoffeeConstants.CafeStatus.InTakeaway then
        str = localize("派送中")
    elseif status == MaidCoffeeConstants.CafeStatus.Resting then
        str = localize("休息中")
    else
        printError("不存在的状态类型 请检查。。。。"..tostring(status))
    end
    local str1 = ""
    if self.parameters.type == MaidCoffeeConstants.SelectType.Manager or self.parameters.type == MaidCoffeeConstants.SelectType.Clerk then
        str1 = localize("餐厅工作？")
    elseif self.parameters.type == MaidCoffeeConstants.SelectType.DeliveryMan then
        str1 = localize("派送外卖？")
    elseif self.parameters.type == MaidCoffeeConstants.SelectType.Lounge then
       str1 = localize("休息室休息？")
    else
        printError("不存在的类型  请检查"..tostring(self.parameters.type))
    end
    local desc = string.format(localize("以下员工正在_target1_，是否前往_target2_？",{_target1_ = string.format("<color=#FF3DC1>%s</color>",str), _target2_ = str1}))
    return desc
end

function OverseaManagePersonnelRoleDialog:OnSure(vo)
    local isToMax = self:JudgeIsPersonMax()
    if isToMax then
        local firstVo = self:GetFirstVoById(self.cacheData[1].id)
        firstVo.cafeStatus = MaidCoffeeConstants.CafeStatus.Non
        self:SetCardStatusById(self.cacheData[1].id,MaidCoffeeConstants.CafeStatus.Non)
        local workType = self:GetWorkType()
        vo.cafeStatus = workType
        self:SetCardStatusById(vo.id,workType)
        table.remove(self.cacheData,1)
        for i, v in pairs(self.cacheData) do
            ---第一位拿掉后 其他卡牌位置往前移一位
            v.index = v.index - 1
        end
        table.insert(self.cacheData,{id = 0,index = #self.cacheData + 1})

        for i, v in pairs(self.cacheData) do
            if v.id == 0 then
                v.id = vo.id
                break
            end
        end

        self:RefreshGridView()
        self:RefreshLeftInfo(vo)
    else
        local go = self.ScrollView:GetShownItemByItemIndex(self.curSelectIndex - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIPersonRoleCellPath)
            if lastScr then
                local pos = 0
                for i, v in pairs(self.cacheData) do
                    if v.id == 0 then
                        v.id = tonumber(vo.id)
                        pos = v.index
                        local workType = self:GetWorkType()
                        vo.cafeStatus = workType
                        self:SetCardStatusById(vo.id,workType)
                        break
                    end
                end
                lastScr:RefreshChooseStatus(true,pos)
                lastScr:RefreshWorkStatus()
                self:RefreshCountShow()
                self:RefreshLeftInfo(vo, true)
            end
        end
    end
end

function OverseaManagePersonnelRoleDialog:GetFirstVoById(id)
    for i, v in pairs(self.showData) do
        if v.id == id then
            return v
        end
    end
    return nil
end

function OverseaManagePersonnelRoleDialog:SetCardStatusById(id,status)
    ---@type CardComponent
    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    cardComponent:UpdateCardDojo(id, {cafeStatus = status})
end

function OverseaManagePersonnelRoleDialog:GetStrByStatus(status)
    local str = ""
    if status == MaidCoffeeConstants.CafeStatus.Non then
        str = localize("")
    elseif status == MaidCoffeeConstants.CafeStatus.UnderManagement then
        str = localize("当前员工正在工作中，无法被选择")
    elseif status == MaidCoffeeConstants.CafeStatus.InService then
        str = localize("当前员工正在工作中，无法被选择")
    elseif status == MaidCoffeeConstants.CafeStatus.InTakeaway then
        str = localize("当前员工正在派送中，无法被选择")
    elseif status == MaidCoffeeConstants.CafeStatus.Resting then
        str = localize("当前员工正在休息中，无法被选择")
    else
        str = localize("不存在的状态  请检查 。。。。"..tostring(status))
    end
    return str
end

function OverseaManagePersonnelRoleDialog:GetIsCanClickByType(status)
    local TypeConfig = TypeConfig[self.parameters.type]
    for i, v in pairs(TypeConfig) do
        if v == status then
            return true
        end
    end
    return false
end

function OverseaManagePersonnelRoleDialog:GetWorkType()
    if self.parameters.type == MaidCoffeeConstants.SelectType.Manager then
        return MaidCoffeeConstants.CafeStatus.UnderManagement
    elseif self.parameters.type == MaidCoffeeConstants.SelectType.Clerk then
        return MaidCoffeeConstants.CafeStatus.InService
    elseif self.parameters.type == MaidCoffeeConstants.SelectType.DeliveryMan then
        return MaidCoffeeConstants.CafeStatus.Non
    elseif self.parameters.type == MaidCoffeeConstants.SelectType.Lounge then
        return MaidCoffeeConstants.CafeStatus.Resting
    else
        printError("不存在的类型  请检查"..tostring(self.parameters.type))
    end
    return nil
end

